pub static INNER_SEA_GODS_FEAT_GAP_ROWS: &[FeatCatalogRecord] = &[
    FeatCatalogRecord { key: "Arcane Insight", category: "General", name: "Arcane Insight", description: Some("Magical insight helps you evade attacks. Whenever you use Arcane Shield, you also gain a +1 insight bonus to AC for 1 round."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Arcane Shield", "PREDEITY:[redacted PI]", "PRESPELLTYPE:1,Arcane=1", "PRETEXT:[redacted PI]", "PREVARGTEQ:Caster_Level_Highest__Arcane,10"]) },
    FeatCatalogRecord { key: "Aura Of Succumbing", category: "General", name: "Aura Of Succumbing", description: Some("Your foul patron's influence hastens death's approach. As a swift action, you can expend one of your uses of channel energy to emanate a 30-foot-radius aura of succumbing for a number of rounds equal to your effective cleric level. Dying creatures in the area take 1 point of damage per die of your normal channel negative energy damage at the start of your turn each round. A successful Will save (DC equal to the DC of your channel energy ability) halves this damage. Whenever a living creature dies while within your aura of succumbing, you gain a number of temporary hit points equal to that creature's Hit Dice. These temporary hit points last for 1 hour."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Four Horsemen", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:Prerequisites: Channel energy class feature, worshiper of one of the Four Horsemen."]) },
    FeatCatalogRecord { key: "Beacon Of Hope", category: "General", name: "Beacon Of Hope", description: Some("Your hope inspires allies in their struggles. When you channel positive energy to heal living creatures, those you heal gain a +2 morale bonus on saving throws, attack rolls, ability checks, and skill checks for a number of rounds equal to your Charisma bonus (minimum 1 round)."), prerequisites: Some(&["PREDEITY:1,Milani", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:Prerequisites: Channel energy 3d6, worshiper of Milani."]) },
    FeatCatalogRecord { key: "Believable Veils", category: "General", name: "Believable Veils", description: Some("The teachings of your deity help you keep your secrets safe. Once per day when you create a glamer or figment effect, you can empower the effect so that the DC to disbelieve it is 2 higher than normal."), prerequisites: Some(&["PRECLASS:1,SPELLCASTER=3", "PREDEITY:1,Sivanah", "PRETEXT:Prerequisites: Caster level 3rd, ability to cast at least one glamer or figment, worshiper of Sivanah."]) },
    FeatCatalogRecord { key: "Bestow Hope", category: "General", name: "Bestow Hope", description: Some("You instill hope in the creatures you heal. When you heal a creature by channeling positive energy, you also relieve its fear. If a creature you heal is shaken, that condition ends. If the creature is frightened, it becomes shaken instead. If the creature is panicked, it becomes frightened instead."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Channel", "PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Blessed Hammer", category: "General", name: "Blessed Hammer", description: Some("Your god's power radiates from your warhammer. You can use any warhammer you wield as a holy symbol when casting spells that require a divine focus or when you channel energy. Furthermore, as a swift action when you cast a divine touch spell, you can choose to have the warhammer carry the charge of the spell instead of your hand. When you deliver a touch spell with your warhammer you can do so as part of melee attack made with the war hammer. If you drop the warhammer or the warhammer is disarmed while carrying a charge, the charge is lost."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRESPELLTYPE:1,Divine=3", "PRETEXT:[redacted PI]", "PREWEAPONPROF:1,Warhammer"]) },
    FeatCatalogRecord { key: "Bloodletting", category: "Combat", name: "Bloodletting", description: Some("When you attack with a piercing or slashing weapon, the wounds you cause bleed profusely. Whenever you threaten a critical hit with a piercing or slashing weapon (regardless of whether you confirm the critical hit or not), you deal 1 point ofbleed damage to the targeted creature."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Bloody Sabres", category: "Combat", name: "Bloody Sabres", description: Some("Imitating the forms of your god, you strike deep and inflict a bloody wound. If you hit an opponent with both your primary weapon and your off-hand weapon as part of the same attack action, and both of those weapons are sawtooth sabres, you deal 1 point ofbleed damage in addition to the normal damage dealt by these attacks."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Exotic Weapon Proficiency (sawtooth sabre),Two-Weapon Fighting", "PREDEITY:1,Achaekek", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,15],[PREVARGTEQ:FeatDexRequirement,15]", "PRETEXT:Prerequisites: Dex 15, Exotic Weapon Proficiency (sawtooth sabre), Two-Weapon Fighting, worshiper of Achaekek."]) },
    FeatCatalogRecord { key: "Bloody Vengeance", category: "Combat", name: "Bloody Vengeance", description: Some("Your retaliatory strikes have long-lasting effects. If an opponent within line of sight has damaged you within the last minute, you may study that opponent as a standard action. Thereafter, if you hit that opponent with a melee attack, you deal 1 point of bleed damage to that creature in addition to the normal damage dealt by your attack."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]", "PRETOTALAB:1"]) },
    FeatCatalogRecord { key: "Bolster Undead", category: "General", name: "Bolster Undead", description: Some("You can fortify undead against positive energy. Whenever you channel negative energy to heal undead creatures, you grant all undead you heal +1 channel resistance (or a +1 bonus to their existing channel resistance) for a number of rounds equal to your Charisma modifier (minimum 1 round)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,6],[PREVARGTEQ:ClericChannelNegativeEnergyDice,6],[PREVARGTEQ:OracleChannelDice,6]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Breaker Of Barriers", category: "Combat", name: "Breaker Of Barriers", description: Some("You see it as your sacred duty to destroy all obstacles. You gain a +2 bonus on Strength checks to break down doors, walls, dams, and other barriers and on combat maneuver checks to bull rush and overrun opponents. You ignore the first 5 points ofhardness when you deal damage to doors, walls, dams, and other barriers."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRESTAT:1,STR=17", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Bullseye Shot", category: "Combat", name: "Bullseye Shot", description: Some("You slow your breath, calm yourself, and hit the bullseye, just as you were trained to do. You can spend a move action to steady your shot. When you do, you gain a +4 bonus on your next ranged attack roll before the end of your turn."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Point-Blank Shot,Precise Shot", "PRETEXT:Prerequisites: Point-Blank Shot, Precise Shot, base attack bonus +5.", "PRETOTALAB:5"]) },
    FeatCatalogRecord { key: "Butterfly's Sting", category: "Combat", name: "Butterfly's Sting", description: Some("You can forgo a critical hit in order to pass it on to an ally. When you confirm a critical hit against a creature, you can choose to forgo the effect of the critical hit and grant a critical hit to the next ally who hits that creature with a melee attack before the start of your next turn. Your attack only deals normal damage, and the next ally to hit the target automatically confirms the attack as a critical hit."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Combat Expertise", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Channel Discord", category: "General", name: "Channel Discord", description: Some("You can focus the Abyss's power to sow discord among those who take damage from your channeled energy. Once per day when you channel negative energy to harm living creatures, in addition to dealing damage you can choose to affect those who fail their Will save against your channel with a song of discord (caster level equal to your effective cleric level)."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Demon Lord", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,8],[PREVARGTEQ:ClericChannelNegativeEnergyDice,8],[PREVARGTEQ:OracleChannelDice,8]", "PRETEXT:Prerequisites: Channel energy 8d6, worshiper of a demon lord."]) },
    FeatCatalogRecord { key: "Channel Endurance", category: "General", name: "Channel Endurance", description: Some("Calling upon the winds and the waves, you prepare your allies for the dangers of the natural world. Once per day when you channel positive energy to heal living creatures, you can choose to grant each healed creature the benefit of endure elements (caster level equal to your effective cleric level). This effect lasts 24 hours."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Channel Hate", category: "General", name: "Channel Hate", description: Some("You masterfully inspire in others violence toward those you hate. As a standard action, you can expend one use of your channel energy ability to affect a single creature within 30 feet as if you had cast venJJeful outraJJeuM (caster level equal to your effective cleric level). Upon obtaining channel energy 9d6, you can affect a number of creatures within 30 feet equal to your Charisma bonus (minimum 2 creatures) with this feat instead. If you expend an extra use of channel energy when using this feat, the target does not gain a second saving throw against this effect if you designate the target's friend or loved one as its hated enemy."), prerequisites: Some(&["PREDEITY:1,Gyronna", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,6],[PREVARGTEQ:ClericChannelNegativeEnergyDice,6],[PREVARGTEQ:OracleChannelDice,6]", "PRETEXT:Prerequisites: Channel energy 6d6, worshiper of Gyronna."]) },
    FeatCatalogRecord { key: "Channel Viciousness", category: "General", name: "Channel Viciousness", description: Some("You can channel brutality into the weapons of your allies. As a standard action, you can expend one of your uses of channel energy to charge the melee weapons of all allies within 30 feet of you with negative energy. Affected melee weapons gain the vicious magic weapon special ability for 1 minute x your Charisma bonus (minimum 1 minute)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,4],[PREVARGTEQ:ClericChannelNegativeEnergyDice,4],[PREVARGTEQ:OracleChannelDice,4]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Charge Of The Righteous", category: "Combat", name: "Charge Of The Righteous", description: Some("You charge toward undead and fiends with confidence in your righteous cause. You do not take a penalty to AC while charging undead creatures and evil outsiders. Normal: When you charge, you take a -2 penalty to AC until the start of your next turn."), prerequisites: Some(&["PREALIGN:LG,CG,NG", "PRETEXT:Prerequisites: Base attack bonus +1, any good alignment.", "PRETOTALAB:1"]) },
    FeatCatalogRecord { key: "Clarifying Channel", category: "General", name: "Clarifying Channel", description: Some("Your channeled energy heals the body and opens the mind to the possibility of true love. Once per day when you channel positive energy to heal living creatures, if any of the creatures you healed are currently affected by one or more charms or compulsions that allowed a saving throw, you grant each of those creatures an immediate save to prematurely end one of those effects. Creatures healed gain a sacred bonus on this save equal to your Charisma bonus (minimum +1)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Conversion Channel", category: "General", name: "Conversion Channel", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Courage In A Bottle", category: "General", name: "Courage In A Bottle", description: Some("You show little fear while inebriated. While you are intoxicated, the bonus you gain from your bravery class feature increases by 2. If this increase grants you a total bonus of +6 or higher against fear effects, you become immune to fear instead."), prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE.Bravery", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Cruelty", category: "General", name: "Cruelty", description: Some("The suffering of others compels you to greater cruelties. Whenever you deal bleed damage to an opponent, cause an opponent to suffer a fear or pain effect, or reduce an opponent's hit points to 0 or fewer, you gain a +2 morale bonus on attack rolls and weapon damage rolls for 1 round."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Curse Of Vengeance", category: "General", name: "Curse Of Vengeance", description: Some("Your deity lays curses upon those who wrong you. Whenever you are rendered helpless or a creature kills you, you can cast a single spell or spell-like ability with the curse descriptor as an immediate action before you become helpless or are killed. The curse must have a casting time of 1 standard action or less and must target the creature who rendered you helpless or who killed you. Ifthe curse has a range oftouch and the attacker is not within your reach, you can deliver it as a ranged touch attack with a range of 30 feet."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Deific Obedience", category: "General", name: "Deific Obedience", description: Some("Your reverence for a deity is so great that daily prayer and minor sacrifices grant you special boons. Each deity requires a different daily obedience, but all obediences take no more than 1 hour per day to perform. Once you've performed the obedience, you gain the benefit of a special ability or resistance as indicated in the \"Obedience\" entry for the god to whom you performed the obedience. If you have at least 12 Hit Dice, you also gain the first boon granted by your deity upon undertaking your obedience. If you have at least 16 Hit Dice, you also gain the deity's second boon. If you have 20 Hit Dice or more, you also gain the deity's third boon. Unless a specific duration or number of uses per day is listed, a boon's effects are constant. Certain prestige classes (see page i98) gain access to these boons at lower levels as a benefit of their prestige class. If you have no levels in one of these prestige classes, you gain the boons marked as exalted boons. If you later take levels in sentinel or evangelist, you lose access to the exalted boons and gain access to the new boons appropriate to your class. If you ever fail to perform a daily obedience, you lose all access to the benefits and boons granted by this feat until you next perform the obedience."), prerequisites: Some(&["PREDEITY:1,Y", "PRESKILL:1,Knowledge (religion)=3", "PRETEXT:Prerequisites: Knowledge (religion) 3 ranks, must worship a deity."]) },
    FeatCatalogRecord { key: "Destroy Identity", category: "Combat", name: "Destroy Identity", description: Some("You can use your weapons to mar your opponents' most distinctive characteristics. Whenever you confirm a critical hit against an opponent, in addition to dealing critical damage as normal, you maim your target so much that it takes 2 points of Charisma damage and becomes staggered for 1 round."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Critical Focus", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]", "PRETOTALAB:11"]) },
    FeatCatalogRecord { key: "Devilish Pride", category: "General", name: "Devilish Pride", description: Some("[redacted PI]"), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Iron Will", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Diabolical Negotiator", category: "General", name: "Diabolical Negotiator", description: Some("You treat the art of negotiation as devilish science. You can add your Intelligence or Wisdom modifier (whichever is higher) on Diplomacy checks in place of your Charisma modifier. You can shift a creature's attitude more than two steps with Diplomacy, and a creature's attitude is only decreased by one step if you roll a natural 1 and fail the check by 5 or more."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Skill Focus (Diplomacy)", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Disciple Of The Sword", category: "General", name: "Disciple Of The Sword", description: Some("[redacted PI]"), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Weapon Focus (longsword)", "PRECLASS:1,Cleric=4,Inquisitor=4", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Divination Guide", category: "General", name: "Divination Guide", description: Some("You deity grants you greater guidance and divine insight. Whenever you cast augury or divination, you receive further guidance from your deity's agents. You gain a +l sacred bonus if your worship a good deity or a +1 profane bonus if you worship an evil deity (if you worship a neutral deity the type ofbonus is either determined by the type of energy you channel with the channel energy class feature or, if you don't have that class ability, your choice upon taking this feat) on all saving throws for 1 minute per caster level of the augury or divination spell you cast."), prerequisites: Some(&["PREDEITY:1,Y", "PRETEXT:Prerequisites: Caster level 3rd, ability to cast augury or divination, must worship a deity.", "PREVARGTEQ:Caster_Level_Highest,3"]) },
    FeatCatalogRecord { key: "Divine Barrier", category: "General", name: "Divine Barrier", description: Some("You have trained in the art ofblocking breath weapons. When you are within an area effect that deals acid, cold, electricity, or fire damage, you can expend one use of your channel energy ability as an immediate action to shield yourself and all allies within 3 0 feet. You and allies within your shield only take half damage if they fail their save against the effect, and those who make a successful save take no damage from the effect."), prerequisites: Some(&["PREDEITY:1,Apsu", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:Prerequisites: Channel energy class feature, worshiper of Apsu."]) },
    FeatCatalogRecord { key: "Divine Dignity", category: "General", name: "Divine Dignity", description: Some("Secrets of the First Vault help you perfect your spellcasting. Three times per day, as a free action when you cast a harmless divine spell or a domain spell, you can choose for the casting to not provoke attacks of opportunity. Special: You can take this feat multiple times. When you do, you can use this feat three more times per day."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Combat Casting", "PREDEITY:[redacted PI]", "PRESPELLTYPE:1,Divine=1", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Divine Expression", category: "General", name: "Divine Expression", description: Some("You mix faith with art to empower your performances. When you take this feat, choose either the cleric or oracle class. Levels in the selected class stack with your bard level when determining the number of rounds per day you can use your bardic performance and the type of action it takes to start a bardic performance."), prerequisites: Some(&["PRECLASS:1,Bard=1", "PRECLASS:1,Cleric=1,Oracle=1", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Dreamed Secrets", category: "General", name: "Dreamed Secrets", description: Some("When you sleep you gain secrets from beyond the stars, but such power comes with a price. With each night's rest, you can choose two spells from the wizard spell list, both of which must be at least 1 wizard spell level lower than the highest level divine spell you can cast. If you are a spontaneous caster, these spells are added to your spells known for 24 hours. If you prepare spells, you can prepare these spells any time you do so in the next 24 hours. Each time you attempt to cast one of the wizard spells you have chosen, you must succeed at a DC 20 Will save or take id2 points of Wisdom damage and fail to cast the spell, though you do not lose the spell."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Great Old One,PANTHEON.Outer God", "PRESPELLTYPE:1,Divine=1", "PRETEXT:Prerequisites: Ability to cast divine spells, caster level 7th, worshiper of a Great Old One or Outer God.", "PREVARGTEQ:Caster_Level_Highest,7"]) },
    FeatCatalogRecord { key: "Drunken Brawler", category: "Combat", name: "Drunken Brawler", description: Some("You have learned how to fight effectively while drunk. When you drink a tankard of ale or strong alcohol, you take a -2 penalty on Reflex saving throws, but gain a number of temporary hit points equal to your character level, and gain a +2 alchemical bonus on Fortitude and Will saving throws. These bonuses last 1 hour or until the temporary hit points gained by this effect are lost, whichever occurs first. Regardless, the penalty lasts for a full hour."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Endurance", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Eerie Sense", category: "General", name: "Eerie Sense", description: Some("You have a knack for sniffing out undead. At the beginning of your turn each round, if you are within 60 feet of an undead creature or a haunt, you get a chill down your spine and instinctively sense that something eerie is very near. This sense does not alert you to the direction of the undead or haunt. Anything that can block detect undead can likewise block this sense."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Elemental Vigor", category: "General", name: "Elemental Vigor", description: Some("You have learned transformative secrets from communing with elemental beings. Whenever you use a polymorph effect to assume the form of an elemental you gain a rush of vital energy. You gain a number of temporary hit points equal to the caster level of the polymorph effect and you gain a +10 foot bonus to your base speed."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Elemental Lord", "PRETEXT:Prerequisite: Worshiper of an elemental lord."]) },
    FeatCatalogRecord { key: "Fateful Channel", category: "General", name: "Fateful Channel", description: Some("Your faith not only heals the body, it tugs the strands offate. When you channel positive energy to heal living creatures, you grant each creature you heal the ability to roll twice and take the better result on a single attack roll, skill check, or saving throw of their choice within a number of rounds equal to your Charisma bonus (minimum 1). Multiple uses of this ability do not stack, but they do reset the effect's duration. A creature can only benefit from one instance of this channel effect at a time."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Fearsome Finish", category: "Combat", name: "Fearsome Finish", description: Some("When you slay enemies, you frighten other opponents. Upon reducing an enemy to 0 or fewer hit points, for the remaining duration of the combat encounter, you gain a +4 bonus on any Intimidate checks made to demoralize opponents who can see both you and the opponent you dropped."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Intimidating Prowess", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Fey Friend", category: "General", name: "Fey Friend", description: Some("Your reverence for the Eldest helps make fey your allies. Fey regard you as akin to them, and the spells and other abilities of fey treat you as fey or your actual type, whichever is more advantageous to you. You gain a +2 bonus on Bluff, Diplomacy, and Sense Motive checks against fey."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Eldest", "PRETEXT:Prerequisite: Worshiper of one of the Eldest."]) },
    FeatCatalogRecord { key: "Flagellant", category: "General", name: "Flagellant", description: Some("You have learned to ignore the effects of pain through long years of exposure to it. You gain a +4 bonus on saving throws against pain effects. Also, you suffer no adverse effect when your nonlethal damage equals your current hit points, and you become staggered when your nonlethal damage exceeds your current hit points. You never fall unconscious due to nonlethal damage. Normal: When your nonlethal damage equals your current hit points, you become staggered. When your nonlethal damage exceeds your current hit points, you fall unconscious."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Endurance", "PREDEITY:[redacted PI]", "PREPCLEVEL:MIN=7", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Forceful Channel", category: "General", name: "Forceful Channel", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Glorious Heat", category: "General", name: "Glorious Heat", description: Some("When you cast divine fire spells, their heat empowers nearby allies. Whenever you cast a divine spell with the fire descriptor, choose a single ally within 30 feet that you can see. That ally heals a number of hit points equal to half your level and gains a +1 morale bonus on attack rolls until the end of its next turn."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRESPELLTYPE:1,Divine=1", "PRETEXT:[redacted PI]", "PREVARGTEQ:Caster_Level_Highest,5"]) },
    FeatCatalogRecord { key: "Hands Of Valor", category: "General", name: "Hands Of Valor", description: Some("Your touch staunches wounds and inspires great deeds. Once per day when you use lay on hands, you can also imbue that ally with valor. In addition to the normal effects of your lay on hands, the targeted ally gains a sacred bonus on attack rolls and on saves against fear effects equal to your Charisma bonus (minimum +1) for 1 minute."), prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE.Lay on hands", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Hellish Shackles", category: "General", name: "Hellish Shackles", description: Some("You can channel the shackles ofHell onto your foes. Once per day when you channel negative energy to damage living creatures, you can attempt to affect damaged creatures with a dimensional anchor. Those damaged must make a successful Will save (DC equal to the DC of the channel effect) in addition to the normal Will save to halve damage from the channeled energy. Those that fail their save against the channeled energy take a -4 penalty on their saving throw against the dimensional anchor effect. Those that fail their second Will save are affected by dimensional anchor for a number of minutes equal to your Charisma modifier (minimum 1 minute)."), prerequisites: Some(&["PREDEITY:1,PANTHEON.Archdevil,PANTHEON.Infernal Duke,Malbranche,Whore Queen", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,5],[PREVARGTEQ:ClericChannelNegativeEnergyDice,5],[PREVARGTEQ:OracleChannelDice,5]", "PRETEXT:Prerequisites: Channel energy 5d6; worshiper of an archdevil, infernal duke, malbranche, or whore queen."]) },
    FeatCatalogRecord { key: "Heroic Interposition", category: "Combat", name: "Heroic Interposition", description: Some("You arrive just when you are most needed to vanquish evil. Once per day, you can move up to your speed as an immediate action, but you must end this movement adjacent to an opponent who is about to make an attack against an ally. As long as you are visible to the opponent you moved next to, that opponent takes a -2 penalty on the attack roll to which you moved in response."), prerequisites: Some(&["PREABILITY:3,CATEGORY=FEAT,Dodge,Improved Initiative,Mobility", "PREDEITY:1,PANTHEON.Empyreal Lord", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRETEXT:Prerequisites: Dex 13, Dodge, Improved Initiative, Mobility, worshiper ofan empyreal lord."]) },
    FeatCatalogRecord { key: "Hunter Of Dahak", category: "General", name: "Hunter Of Dahak", description: Some("You viciously hunt and sacrifice metallic dragons. Your favored enemy bonuses increase by 2 against metallic dragons."), prerequisites: Some(&["PREDEITY:1,Dahak", "PRETEXT:Prerequisites: Favored enemy (dragon), worshiper of Dahak."]) },
    FeatCatalogRecord { key: "Intrepid Rescuer", category: "Combat", name: "Intrepid Rescuer", description: Some("You instinctively react to interfere with foes that attack your allies or innocents. Whenever an opponent you threaten makes an attack against a helpless, prone, or stunned ally or any attack against a noncombatant, that opponent provokes an attack of opportunity from you. If your attack of opportunity hits your foe, she takes a -4 penalty on the attack roll that provoked this attack of opportunity."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Combat Reflexes", "PREDEITY:1,Kurgess", "PRETEXT:Prerequisites: Combat Reflexes, worshiper of Kurgess."]) },
    FeatCatalogRecord { key: "Ironbound Master", category: "General", name: "Ironbound Master", description: Some("You wear your heavy armor like a second skin. You gain the armor training fighter class feature with an effective fighter level equal to your cleric level -4."), prerequisites: Some(&["PRECLASS:1,Cleric=7", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Ki Channel", category: "General", name: "Ki Channel", description: Some("When you channel positive energy, you can also channel ki. When you channel positive to heal living creatures, any creature that could be healed by the channeled energy can choose to regain ki from it instead. Affected creatures regain a number of ki points equal to the number of dice healed by the channel. creature regaining ki in such a way must either regain ki or be healed by the channel (it cannot gain both)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Liberation Channel", category: "General", name: "Liberation Channel", description: Some("Your channeled energy is truly liberating. When you channel positive energy, any creature healed by the channel also gains the effect of freedom of movement for a number of rounds equal to your Charisma modifier (minimum 1 round). This effect has a caster level equal to your effective cleric level."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Magical Epiphany", category: "General", name: "Magical Epiphany", description: Some("Your faith allows you to prepare a spell when you need it. Once per day, you can prepare a spell in an open spell slot as a standard action."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Master Of Knowledge", category: "General", name: "Master Of Knowledge", description: Some("In times of need, you have the answers. Choose a single Knowledge skill with which you have Skill Focus. Once per day, when you wish to make a check with that Knowledge skill, you need not roll, and may treat the result as if you had rolled a natural 20 instead."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Skill Focus (Knowledge%", "PREDEITY:[redacted PI]", "PRESTAT:1,INT=17", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Measured Response", category: "Combat", name: "Measured Response", description: Some("You believe that a conservative but consistent response guarantees success. When you hit an opponent with a melee or ranged weapon attack, you may choose to deal average damage (rounded down), as if you had rolled exactly the average amount on the damage die or dice. You add your damage bonuses and penalties as normal."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]", "PRETOTALAB:1"]) },
    FeatCatalogRecord { key: "Merciless Rush", category: "Combat", name: "Merciless Rush", description: Some("Though hordes stand against you, they rarely stand long. When you bull rush a creature and your check exceeds the target's CMD by 5 or more, you deal damage equal to your Strength modifier to that target."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Bull Rush", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Messenger Of Fate", category: "General", name: "Messenger Of Fate", description: Some("The Lady of Graves has blessed you with the power of true prophecy. When casting divination spells, you do so at +1 caster level. If your divination spell has a base percentage chance of providing correct or useful information, your maximum chance of gleaning correct or useful information is 100%, instead of the standard 90%."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Nightmare Scars", category: "General", name: "Nightmare Scars", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Nimble Natural Summons", category: "General", name: "Nimble Natural Summons", description: Some("Your summoned natural allies may walk the wild parts of the world unimpeded. Creatures you summon with summon nature's ally can move through any sort of undergrowth (such as natural thorns, briars, and similar terrain) at their normal speeds without taking damage or suffering other impairment. Thorns, briars, and undergrowth areas that have been magically manipulated to impede motion, however, still affect summoned creatures."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Augmented Summoning,Spell Focus (conjuration)", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]", "PREVARGTEQ:Caster_Level_Highest,6"]) },
    FeatCatalogRecord { key: "Oath Of The Unbound", category: "General", name: "Oath Of The Unbound", description: Some("You have sworn never to be shackled. You gain a +2 bonus on combat maneuver checks to break free of a grapple or pin, on Strength checks to burst bonds or to break through doors or walls, and on saving throws to resist spells and effects that would entangle or slow you."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Ordered Mind", category: "General", name: "Ordered Mind", description: Some("You can modify a variety of your spells to use as counterspells. The DC of your Spellcraft check to identify an opponent's spell is equal to 20 + the spell level of the opponent's spell, but for your counterspell you can cast any spell from the same school of your foe's spell. The level of the spell used to counterspell must be equal to or higher than the level of your foe's spell. Normal: The Spellcraft DC to identify an opponent's spell is equal to i5 + the spell's level. Generally, a spell can only counter itself."), prerequisites: Some(&["PREALIGN:LN,LE,LG", "PRETEXT:Prerequisites: Caster level 7th, any lawful alignment.", "PREVARGTEQ:Caster_Level_Highest,7"]) },
    FeatCatalogRecord { key: "Perfect Casting", category: "General", name: "Perfect Casting", description: Some("You unlock greater secrets of divine spellcasting from the First Vault. When you use Divine Dignity, it can affect the casting of any of your divine spells, not just harmless and domain spells."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Combat Casting,Divine Dignity", "PREDEITY:[redacted PI]", "PRESPELLTYPE:1,Divine=1", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Persuasive Performer", category: "General", name: "Persuasive Performer", description: Some("For you, performance is the heart of negotiation. You can use any of your Perform skills in place of Diplomacy, not just Perform (keyboard instruments, oratory, string, or wind). If you do use Perform (keyboard instruments, oratory, string, or wind), you gain a +2 bonus on your check."), prerequisites: Some(&["PREABILITY:2,CATEGORY=Special Ability,TYPE.Versatile Performance", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Poisoner's Channel", category: "General", name: "Poisoner's Channel", description: Some("You cause anyone damaged by your negative energy to become susceptible to poison. Once per day when you channel negative energy to damage living creatures, you can cause any creatures that failed their save against your channel to take a -4 penalty on saving throws against poison effects. This penalty lasts for 1 minute."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Potion Glutton", category: "General", name: "Potion Glutton", description: Some("You gulp down potions with unsettling speed. You can drink potions, elixirs, or other potables as a swift action without provoking attacks of opportunity. Normal: Drinking potions is a move action that provokes attacks of opportunity."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Protective Channel", category: "General", name: "Protective Channel", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:1,lomedae", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:Prerequisites: Channel energy 7d6, worshiper of lomedae."]) },
    FeatCatalogRecord { key: "Protector's Strike", category: "General", name: "Protector's Strike", description: Some("You can use your smiting power to protect an ally from known evil. When you choose the target of your smite evil ability, you also choose one creature other than you within line of sight. While your smite is in effect, the additional creature you chose gains a deflection bonus to AC equal to your Charisma modifier against attacks made by the target of the smite. This bonus ends when the smite ends. You do not gain the deflection bonus to AC normally granted by smite evil. Normal: While smite evil is in effect, the paladin gains a deflection bonus to her AC equal to her Charisma bonus (if any) against attacks made by the target of her smite attack."), prerequisites: Some(&["PREABILITY:2,CATEGORY=Special Ability,Smite Evil", "PRETEXT:Prerequisites: Base attack bonus +5, smite evil class feature.", "PRETOTALAB:5"]) },
    FeatCatalogRecord { key: "Reject Poison", category: "General", name: "Reject Poison", description: Some("You are a careful poisoner, and know how to protect yourself against exposure to the ill effects of most substances. Whenever you fail the initial saving throw against poison, you have a 20% chance of naturally rejecting the toxin, negating its effects and wasting its use."), prerequisites: Some(&["PREABILITY:2,CATEGORY=Special Ability,TYPE.Poison Use", "PREDEITY:[redacted PI]", "PRESTAT:1,CON=13", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Riptide Attack", category: "Combat", name: "Riptide Attack", description: Some("You can immediately drag opponents you successfully trip. Whenever you succeed at a trip combat maneuver, you can automatically attempt a drag combat maneuver against your tripped target as a swift action."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Improved Drag,Improved Trip", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Savior's Arrow", category: "General", name: "Savior's Arrow", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]", "PREWEAPONPROF:1,Longbow"]) },
    FeatCatalogRecord { key: "Seductive Channel", category: "General", name: "Seductive Channel", description: Some("Even your healing is seductive. When you channel positive energy, those you heal can choose to take additional healing equal to your Charisma bonus (minimum 1), but in return they take a -2 penalty on Will saves against your charms, compulsions, and emotion effects and on Sense Motive checks against your Bluff checks. This penalty lasts for 24 hours. A creature cannot benefit from this feat again for the duration of this penalty."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Shadow Dodge", category: "General", name: "Shadow Dodge", description: Some("You use shadows to confound your enemies' senses. You can use the light around you to move back and forth from shadow to light again, and your sudden shifting confuses your enemies' eyes. Each time you move a distance equal to or greater than your speed in areas of normal light or dim light, you gain a +3 dodge bonus to AC until the start of your next turn. Enemies who do not use sight in order to perceive you or are using true seeing or a similar effect ignore this AC bonus. This feat is ineffective in areas of darkness or bright light, where one cannot readily shift between light and shadow."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Shatter Resolve", category: "General", name: "Shatter Resolve", description: Some("Your negative energy causes despair in those you harm. When you damage a creature by channeling negative energy, you fill your foe with fear. A creature that fails its Will save against your channeled energy also becomes shaken for a number of rounds equal to the number of dice you roll for your channel energy ability."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,1],[PREVARGTEQ:ClericChannelNegativeEnergyDice,1],[PREVARGTEQ:OracleChannelDice,1]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Siphon Channel", category: "General", name: "Siphon Channel", description: Some("You can channel negative energy to feed off the suffering of others. Once per day when you channel negative energy to damage living creatures, you gain a number oftemporary hit points equal to half the die result of your channeled energy + 1 per creature affected by the channeled energy. For each affected creature that did not succeed at its saving throw against the channeled energy, you gain an additional temporary hit point. These temporary hit points disappear after 1 hour."), prerequisites: Some(&["PREDEITY:1,Ghlaunder", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:Prerequisites: Channel energy 3d6, worshiper of Ghlaunder."]) },
    FeatCatalogRecord { key: "Spear Dancer", category: "Combat", name: "Spear Dancer", description: Some("You incorporate your two-handed reach weapon into a dizzying martial dance. Each time you hit a creature with a twohanded reach weapon that you have Weapon Focus in, the creature is dazzled for 1 round."), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Weapon Focus", "PRESKILL:1,Perform (Dance)=4", "PRETEXT:Prerequisites: Weapon Focus (any two-handed reach weapon), Perform (dance) 4 ranks."]) },
    FeatCatalogRecord { key: "Spiked Destroyer", category: "Combat", name: "Spiked Destroyer", description: Some("You can attack with your armor spikes while using bull rush or overrun. When you succeed at a bull rush or overrun combat maneuver, you may automatically make an attack roll with your armor spikes against the target of the maneuver as a swift action, using your highest attack bonus."), prerequisites: Some(&["PRETEXT:Prerequisite: Proficient with armor spikes."]) },
    FeatCatalogRecord { key: "Squash Flat", category: "Combat", name: "Squash Flat", description: Some("You can bull rush an opponent straight to the ground. Whenever you make a bull rush attack and your combat maneuver check exceeds the target's CMD by 5 or more, you can attempt to trip the target as part of your bull rush as a free action. This does not provoke an attack of opportunity."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Improved Bull Rush,Merciless Rush", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Steady Engagement", category: "Combat", name: "Steady Engagement", description: Some("You can draw on your excellent balance to trip or disarm opponents when they try to disengage. If you use Stand Still to prevent an opponent from moving, you may make a disarm or trip combat maneuver against your target as an immediate action."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Combat Reflexes,Stand Still", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Steelskin Channel", category: "General", name: "Steelskin Channel", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Stone Read", category: "General", name: "Stone Read", description: Some("Faint vibrations in stone can alert you to trouble. You gain a +3 bonus on Perception checks in underground or mountainous environments. If you have 10 or more ranks in Knowledge (dungeoneering), this bonus increases to +6."), prerequisites: Some(&["PRESKILL:1,Knowledge (dungeoneering)=4", "PRETEXT:Prerequisite: Knowledge (dungeoneering) 4 ranks."]) },
    FeatCatalogRecord { key: "Stone Strider", category: "General", name: "Stone Strider", description: Some("You discern the best path through rocky terrain. You can move through any sort of nonmagical rocky terrain without taking damage, becoming slowed due to difficult terrain, or suffering any other impairments the terrain would otherwise cause."), prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Dwarf ~ Stonecunning", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Sun Striker", category: "Combat", name: "Sun Striker", description: Some("Called by the Dawnflower to strike down the undead, your scimitar becomes an agent ofher burning will. Whenever you confirm a critical hit against an undead creature, your attack bypasses all DR, deals full damage to incorporeal creatures, and acts as though it has the flaming burst weapon special ability."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Critical Focus,Weapon Focus (scimitar)", "PREDEITY:[redacted PI]", "PREPCLEVEL:MIN=7", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Thicket Channel", category: "General", name: "Thicket Channel", description: Some("Your deity infuses your channeled energy with bounty. When you channel positive energy, you can cause plants in the affected area to grow as though targeted by the overgrowth version of plant srowth (caster level equal to your effective cleric level)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,7],[PREVARGTEQ:ClericChannelNegativeEnergyDice,7],[PREVARGTEQ:OracleChannelDice,7]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "To The Last", category: "Combat", name: "To The Last", description: Some("Your devotion to battle inspires you to fight competently until death claims you. When you are disabled, you are not staggered, though performing standard actions still deals 1 point of damage to you. Taking a full-round action deals 2 points of damage to you."), prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Diehard,Endurance", "PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Torch Bearer", category: "Combat", name: "Torch Bearer", description: Some("You can make use of a torch as a deadly, macelike weapon. You treat a torch as a light weapon that deals bludgeoning damage equal to that of a light mace of its size plus 1 point of fire damage, and you do not incur penalties as you would for using it as an improvised weapon. Normal: A torch used in combat is treated as a one-handed improvised weapon that deals bludgeoning damage equal to that of a gauntlet of its size plus 1 point of fire damage."), prerequisites: None },
    FeatCatalogRecord { key: "Trailblazing Channel", category: "General", name: "Trailblazing Channel", description: Some("Your positive energy makes trailblazers of those you heal. Once per day when you channel positive energy, you can cause healed creatures to be unimpeded by difficult terrain for a number of minutes equal to your Charisma modifier (minimum 1 minute)."), prerequisites: Some(&["PREDEITY:[redacted PI]", "PREMULT:1,[PREVARGTEQ:ClericChannelPositiveEnergyDice,3],[PREVARGTEQ:ClericChannelNegativeEnergyDice,3],[PREVARGTEQ:OracleChannelDice,3]", "PRETEXT:[redacted PI]"]) },
    FeatCatalogRecord { key: "Undermining Exploit", category: "General", name: "Undermining Exploit", description: Some("Your familiarity with earth and stone gives you a distinct advantage on rocky battlefields. You gain a +4 insight bonus on combat maneuver checks against opponents occupying a square of rocky difficult terrain such as rubble, broken ground, or steep stairs."), prerequisites: Some(&["PRESKILL:1,Knowledge (dungeoneering)=4", "PRETEXT:Prerequisite: Knowledge (dungeoneering) 4 ranks."]) },
    FeatCatalogRecord { key: "Wave Master", category: "General", name: "Wave Master", description: Some("[redacted PI]"), prerequisites: Some(&["PREDEITY:[redacted PI]", "PRETEXT:[redacted PI]"]) },
];
